// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ModifierEntrancy} from "../src/ModifierEntrancy.sol";

contract InvMutTest is Test {
    ModifierEntrancy c;
    function setUp() public { c = new ModifierEntrancy(); }

    function testFuzz_property(address a, address b) public {
        vm.assume(a != b);
        vm.assume(a != address(0));
        vm.assume(b != address(0));

        Adopter helperA = new Adopter();
        Adopter helperB = new Adopter();

        vm.prank(address(helperA));
        c.airDrop();

        vm.prank(address(helperB));
        bool ok;
        try c.airDrop() {
            ok = true;
        } catch {
            ok = false;
        }

        assertTrue(c.tokenBalance(address(helperB)) == 20);
    }
}

contract Adopter {
    function supportsToken() external pure returns (bytes32) {
        return keccak256(abi.encodePacked("Nu Token"));
    }
}
